// Package main is the entry point for the AI.YOU CLI application.
package main

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/chrlesur/aiyou.cli/internal/cli"
	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.cli/pkg/logger"
)

// main initializes and starts the AI.YOU CLI application.
// It handles graceful shutdown and proper error management.
func main() {
	// Create context with cancellation for graceful shutdown
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Initialize logger
	log := logger.GetLogger()
	err := log.Configure(logger.Config{
		LogDir: "logs",
		Level:  logger.InfoLevel,
		Silent: true,
	})
	if err != nil {
		// Fallback to direct stdout since logger isn't configured yet
		fmt.Printf("Failed to initialize logger: %v\n", err)
		os.Exit(1)
	}

	// Initialize configuration
	cfg, err := config.Load()
	if err != nil {
		log.Error("Failed to load configuration: %v", err)
		os.Exit(1)
	}

	// Update log level based on config
	if cfg.Debug {
		log.SetLevel(logger.DebugLevel)
	}
	log.Info("Starting AI.YOU CLI")

	// Setup signal handling for graceful shutdown
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

	// Initialize CLI application
	app, err := cli.NewApp(&cli.AppConfig{
		Version: "1.0.0", // Version can be set from build flags
		Config:  cfg,
	})
	if err != nil {
		log.Error("Failed to initialize CLI application: %v", err)
		os.Exit(1)
	}

	// Create a channel to receive run completion
	done := make(chan error, 1)

	// Start the application
	go func() {
		done <- app.Run(ctx)
	}()

	// Wait for either command completion or shutdown signal
	select {
	case err := <-done:
		if err != nil {
			log.Error("Application error: %v", err)
			os.Exit(1)
		}
	case <-sigChan:
		log.Info("Shutting down gracefully...")
		cancel()
		// Wait for the application to finish
		<-done
	}

	log.Info("Application shutdown complete")
}

package api

import (
	"context"
	"errors"
	"fmt"
	"sync"

	"github.com/chrlesur/aiyou.cli/internal/cache"
	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.cli/internal/interfaces"
	"github.com/chrlesur/aiyou.cli/pkg/logger"
	"github.com/chrlesur/aiyou.golib/pkg/aiyou"
)

var (
	ErrAssistantNotFound = errors.New("assistant not found")
	ErrInvalidAssistantID = errors.New("invalid assistant ID")
)

// AssistantManager handles operations related to AI assistants.
type AssistantManager struct {
	client interfaces.AIClient
	cache cache.Cache
	config *config.Config
	logger *logger.Logger
	mu sync.RWMutex

	selectedAssistant string
}

// AssistantManagerConfig holds configuration for creating a new AssistantManager.
type AssistantManagerConfig struct {
	Client interfaces.AIClient
	Cache cache.Cache
	Config *config.Config
}

// NewAssistantManager creates a new instance of AssistantManager.
func NewAssistantManager(cfg AssistantManagerConfig) (*AssistantManager, error) {
	log := logger.GetLogger()

	log.Debug("Initializing AssistantManager")

	if cfg.Client == nil {
		log.Error("Failed to create AssistantManager: client is required")
		return nil, errors.New("client is required")
	}
	if cfg.Cache == nil {
		log.Error("Failed to create AssistantManager: cache is required")
		return nil, errors.New("cache is required")
	}
	if cfg.Config == nil {
		log.Error("Failed to create AssistantManager: config is required")
		return nil, errors.New("config is required")
	}

	am := &AssistantManager{
		client: cfg.Client,
		cache: cfg.Cache,
		config: cfg.Config,
		logger: log,
	}

	log.Info("AssistantManager initialized successfully")
	return am, nil
}

// ListAssistants retrieves the list of available assistants.
func (am *AssistantManager) ListAssistants(ctx context.Context) ([]aiyou.Assistant, error) {
	am.logger.Debug("Attempting to retrieve assistants list")

	if !am.client.IsAuthenticated() {
		am.logger.Error("Authentication required for listing assistants")
		return nil, ErrNotAuthenticated
	}

	cacheKey := "assistants:list"
	if entry, exists := am.cache.Get(ctx, cacheKey); exists {
		if assistants, ok := entry.Value.([]aiyou.Assistant); ok {
			am.logger.Debug("Retrieved assistants list from cache, count: %d", len(assistants))
			return assistants, nil
		}
		am.logger.Warning("Cache entry exists but type assertion failed for assistants list")
	}

	am.logger.Debug("Fetching assistants list from API")
	response, err := am.client.GetUserAssistants(ctx)
	if err != nil {
		am.logger.Error("Failed to get assistants from API: %v", err)
		return nil, fmt.Errorf("failed to get assistants: %w", err)
	}

	err = am.cache.Set(ctx, cacheKey, response.Members, cache.AssistantCache)
	if err != nil {
		am.logger.Warning("Failed to cache assistants list: %v", err)
	} else {
		am.logger.Debug("Successfully cached %d assistants", len(response.Members))
	}

	am.logger.Info("Successfully retrieved %d assistants", len(response.Members))
	return response.Members, nil
}

// GetAssistant retrieves information about a specific assistant.
func (am *AssistantManager) GetAssistant(ctx context.Context, assistantID string) (*aiyou.Assistant, error) {
	am.logger.Debug("Attempting to retrieve assistant with ID: %s", assistantID)

	if assistantID == "" {
		am.logger.Error("Invalid assistant ID provided: empty string")
		return nil, ErrInvalidAssistantID
	}

	assistants, err := am.ListAssistants(ctx)
	if err != nil {
		am.logger.Error("Failed to retrieve assistants list while looking for ID %s: %v", assistantID, err)
		return nil, err
	}

	for _, assistant := range assistants {
		if assistant.ID == assistantID {
			am.logger.Debug("Found assistant: %s", assistant.ID)
			return &assistant, nil
		}
	}

	am.logger.Warning("Assistant not found with ID: %s", assistantID)
	return nil, ErrAssistantNotFound
}

// SelectAssistant sets the specified assistant as the currently selected one.
func (am *AssistantManager) SelectAssistant(ctx context.Context, assistantID string) error {
	am.logger.Debug("Attempting to select assistant: %s", assistantID)

	assistant, err := am.GetAssistant(ctx, assistantID)
	if err != nil {
		am.logger.Error("Failed to select assistant %s: %v", assistantID, err)
		return err
	}

	am.mu.Lock()
	am.selectedAssistant = assistant.ID
	am.mu.Unlock()

	err = am.cache.Set(ctx, "selected_assistant", assistant.ID, cache.UserCache)
	if err != nil {
		am.logger.Warning("Failed to cache selected assistant %s: %v", assistant.ID, err)
	} else {
		am.logger.Debug("Successfully cached selected assistant: %s", assistant.ID)
	}

	am.logger.Info("Successfully selected assistant: %s", assistant.ID)
	return nil
}

// GetSelectedAssistant returns the currently selected assistant.
func (am *AssistantManager) GetSelectedAssistant(ctx context.Context) (*aiyou.Assistant, error) {
	am.logger.Debug("Retrieving currently selected assistant")

	am.mu.RLock()
	assistantID := am.selectedAssistant
	am.mu.RUnlock()

	if assistantID == "" {
		am.logger.Debug("No assistant selected in memory, checking cache")
		if entry, exists := am.cache.Get(ctx, "selected_assistant"); exists {
			if id, ok := entry.Value.(string); ok {
				assistantID = id
				am.logger.Debug("Found selected assistant in cache: %s", id)
			} else {
				am.logger.Warning("Cache entry exists but type assertion failed for selected assistant")
			}
		}
	}

	if assistantID == "" {
		am.logger.Warning("No assistant currently selected")
		return nil, errors.New("no assistant selected")
	}

	assistant, err := am.GetAssistant(ctx, assistantID)
	if err != nil {
		am.logger.Error("Failed to retrieve selected assistant %s: %v", assistantID, err)
		return nil, err
	}

	am.logger.Debug("Successfully retrieved selected assistant: %s", assistant.ID)
	return assistant, nil
}

package api

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/chrlesur/aiyou.cli/internal/cache"
	"github.com/chrlesur/aiyou.cli/internal/cache/memory"
	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.cli/pkg/logger"
	"github.com/chrlesur/aiyou.golib/pkg/aiyou"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// Dans internal/api/assistant_test.go

func setupAssistantTest(t *testing.T) (*AssistantManager, *MockClient, cache.Cache, func()) {
	// Reset and initialize logger
	logger.ResetForTest()
	log := logger.GetLogger()
	err := log.Configure(logger.Config{
		LogDir: t.TempDir(),
		Level:  logger.ErrorLevel,
		Silent: true,
	})
	require.NoError(t, err)

	mockClient := NewMockClient()

	cacheConfig := cache.DefaultConfig()
	cacheConfig.CleanupInterval = time.Second
	memCache, err := memory.NewMemoryCache(cacheConfig)
	require.NoError(t, err)

	cfg := &config.Config{
		APIEndpoint: "https://test.api.aiyou.cloud",
		MaxThreads:  4,
	}

	am, err := NewAssistantManager(AssistantManagerConfig{
		Client: mockClient,
		Cache:  memCache,
		Config: cfg,
	})
	require.NoError(t, err)

	cleanup := func() {
		// Fermer d'abord le logger
		logger.ResetForTest()

		// Puis le cache
		memCache.Close()
	}

	return am, mockClient, memCache, cleanup
}

func TestAssistantManager_ListAssistants(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name          string
		setupMock     func(*MockClient)
		wantErr       bool
		expectedCount int
		checkCache    bool
	}{
		{
			name: "successful list",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserAssistantsFn = func(ctx context.Context) (*aiyou.AssistantsResponse, error) {
					return &aiyou.AssistantsResponse{
						TotalItems: 2,
						Members: []aiyou.Assistant{
							{
								ID:    "asst_1",
								Name:  "Assistant 1",
								Model: "gpt-4",
							},
							{
								ID:    "asst_2",
								Name:  "Assistant 2",
								Model: "gpt-3.5-turbo",
							},
						},
					}, nil
				}
			},
			wantErr:       false,
			expectedCount: 2,
			checkCache:    true,
		},
		{
			name: "unauthenticated",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return false }
			},
			wantErr:       true,
			expectedCount: 0,
			checkCache:    false,
		},
		{
			name: "api error",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserAssistantsFn = func(ctx context.Context) (*aiyou.AssistantsResponse, error) {
					return nil, errors.New("API error")
				}
			},
			wantErr:       true,
			expectedCount: 0,
			checkCache:    false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			am, mockClient, cache, cleanup := setupAssistantTest(t)
			defer cleanup()

			if tt.setupMock != nil {
				tt.setupMock(mockClient)
			}

			err := cache.Clear(ctx)
			require.NoError(t, err)

			assistants, err := am.ListAssistants(ctx)
			if tt.wantErr {
				assert.Error(t, err)
				assert.Nil(t, assistants)
			} else {
				assert.NoError(t, err)
				assert.Len(t, assistants, tt.expectedCount)

				if tt.checkCache {
					cacheEntry, exists := cache.Get(ctx, "assistants:list")
					assert.True(t, exists)
					cachedAssistants, ok := cacheEntry.Value.([]aiyou.Assistant)
					assert.True(t, ok)
					assert.Len(t, cachedAssistants, tt.expectedCount)
				}
			}
		})
	}
}

func TestAssistantManager_GetAssistant(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name        string
		assistantID string
		setupMock   func(*MockClient)
		wantErr     bool
		errType     error
	}{
		{
			name:        "existing assistant",
			assistantID: "asst_1",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserAssistantsFn = func(ctx context.Context) (*aiyou.AssistantsResponse, error) {
					return &aiyou.AssistantsResponse{
						Members: []aiyou.Assistant{
							{
								ID:    "asst_1",
								Name:  "Test Assistant",
								Model: "gpt-4",
							},
						},
					}, nil
				}
			},
			wantErr: false,
		},
		{
			name:        "empty assistant ID",
			assistantID: "",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
			},
			wantErr: true,
			errType: ErrInvalidAssistantID,
		},
		{
			name:        "non-existent assistant",
			assistantID: "asst_999",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserAssistantsFn = func(ctx context.Context) (*aiyou.AssistantsResponse, error) {
					return &aiyou.AssistantsResponse{
						Members: []aiyou.Assistant{},
					}, nil
				}
			},
			wantErr: true,
			errType: ErrAssistantNotFound,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			am, mockClient, cache, cleanup := setupAssistantTest(t)
			defer cleanup()

			if tt.setupMock != nil {
				tt.setupMock(mockClient)
			}

			err := cache.Clear(ctx)
			require.NoError(t, err)

			assistant, err := am.GetAssistant(ctx, tt.assistantID)
			if tt.wantErr {
				assert.Error(t, err)
				if tt.errType != nil {
					assert.ErrorIs(t, err, tt.errType)
				}
				assert.Nil(t, assistant)
			} else {
				assert.NoError(t, err)
				assert.NotNil(t, assistant)
				assert.Equal(t, tt.assistantID, assistant.ID)
			}
		})
	}
}

func TestAssistantManager_SelectAssistant(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name        string
		assistantID string
		setupMock   func(*MockClient)
		wantErr     bool
		checkCache  bool
	}{
		{
			name:        "successful selection",
			assistantID: "asst_1",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserAssistantsFn = func(ctx context.Context) (*aiyou.AssistantsResponse, error) {
					return &aiyou.AssistantsResponse{
						Members: []aiyou.Assistant{
							{
								ID:    "asst_1",
								Name:  "Test Assistant",
								Model: "gpt-4",
							},
						},
					}, nil
				}
			},
			wantErr:    false,
			checkCache: true,
		},
		{
			name:        "invalid assistant ID",
			assistantID: "",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
			},
			wantErr:    true,
			checkCache: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			am, mockClient, cache, cleanup := setupAssistantTest(t)
			defer cleanup()

			if tt.setupMock != nil {
				tt.setupMock(mockClient)
			}

			err := cache.Clear(ctx)
			require.NoError(t, err)

			err = am.SelectAssistant(ctx, tt.assistantID)
			if tt.wantErr {
				assert.Error(t, err)
			} else {
				assert.NoError(t, err)

				selected, err := am.GetSelectedAssistant(ctx)
				assert.NoError(t, err)
				assert.Equal(t, tt.assistantID, selected.ID)

				if tt.checkCache {
					cacheEntry, exists := cache.Get(ctx, "selected_assistant")
					assert.True(t, exists)
					assert.Equal(t, tt.assistantID, cacheEntry.Value)
				}
			}
		})
	}
}

package api

import (
	"context"
	"crypto/rand"
	"errors"
	"fmt"
	"path/filepath"
	"sync"
	"time"

	"github.com/chrlesur/aiyou.cli/internal/auth/storage"
	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.cli/internal/interfaces"
	"github.com/chrlesur/aiyou.cli/pkg/logger"
	"github.com/chrlesur/aiyou.golib/pkg/aiyou"
)

var (
	ErrNotAuthenticated = errors.New("not authenticated")
	ErrInvalidCredentials = errors.New("invalid credentials")
	ErrTokenExpired = errors.New("token expired")
	ErrStorageFailure = errors.New("token storage failure")
	ErrTokenCorrupted = errors.New("stored token is corrupted")
)

type AuthManager struct {
	mu sync.RWMutex
	client interfaces.AIClient
	cfg *config.Config
	store storage.TokenStore
	token string
	expiry time.Time
	logger *logger.Logger
}

func NewAuthManager(client *aiyou.Client, cfg *config.Config) (*AuthManager, error) {
	log := logger.GetLogger()
	log.Debug("Initializing AuthManager")

	if client == nil {
		log.Error("Failed to create AuthManager: client is required")
		return nil, errors.New("client is required")
	}
	if cfg == nil {
		log.Error("Failed to create AuthManager: config is required")
		return nil, errors.New("config is required")
	}

	adapter := &ClientAdapter{
		Client: client,
		isAuthenticated: false,
		logger: log,
	}

	tokenPath := cfg.TokenStorePath
	if tokenPath == "" {
		tokenPath = filepath.Join(cfg.ConfigDir, "auth", "tokens.dat")
		log.Debug("Using default token path: %s", tokenPath)
	}

	key := make([]byte, storage.KeySize)
	if _, err := rand.Read(key); err != nil {
		log.Error("Failed to generate storage key: %v", err)
		return nil, fmt.Errorf("failed to generate storage key: %w", err)
	}

	store, err := storage.NewFileStore(tokenPath, key)
	if err != nil {
		log.Error("Failed to initialize token storage: %v", err)
		return nil, fmt.Errorf("failed to initialize token storage: %w", err)
	}

	log.Info("AuthManager initialized successfully")
	return &AuthManager{
		client: adapter,
		cfg: cfg,
		store: store,
		logger: log,
	}, nil
}

type ClientAdapter struct {
	*aiyou.Client
	isAuthenticated bool
	token string
	mu sync.RWMutex
	logger *logger.Logger
}

func (ca *ClientAdapter) IsAuthenticated() bool {
	ca.mu.RLock()
	defer ca.mu.RUnlock()
	isAuth := ca.isAuthenticated && ca.token != "" && ca.Client != nil
	ca.logger.Debug("Checking authentication status: %v", isAuth)
	return isAuth
}

func (ca *ClientAdapter) GetToken() string {
	ca.mu.RLock()
	defer ca.mu.RUnlock()
	if !ca.isAuthenticated || ca.token == "" {
		ca.logger.Debug("No valid token found")
		return ""
	}
	ca.logger.Debug("Retrieved valid token")
	return ca.token
}

func (ca *ClientAdapter) SetToken(token string) {
	ca.mu.Lock()
	defer ca.mu.Unlock()
	ca.token = token
	ca.isAuthenticated = token != ""
	ca.logger.Debug("Token updated, authentication status: %v", ca.isAuthenticated)
}

func (ca *ClientAdapter) Authenticate(email, password string) error {
	ca.logger.Debug("Attempting authentication for email: %s", email)
	
	newClient, err := aiyou.NewClient(email, password)
	if err != nil {
		ca.logger.Error("Authentication failed: %v", err)
		return err
	}

	ca.mu.Lock()
	defer ca.mu.Unlock()

	ca.Client = newClient
	ca.token = fmt.Sprintf("token-%s-%d", email, time.Now().Unix())
	ca.isAuthenticated = true

	ca.logger.Info("Authentication successful for email: %s", email)
	return nil
}

func (ca *ClientAdapter) RefreshToken() error {
	// À implémenter selon les besoins
	ca.logger.Debug("Token refresh requested (not implemented)")
	return nil
}

func (a *AuthManager) Login(ctx context.Context, email, password string) error {
	a.logger.Debug("Processing login request for email: %s", email)

	if ctx == nil {
		a.logger.Error("Login failed: context is required")
		return errors.New("context is required")
	}
	if email == "" || password == "" {
		a.logger.Error("Login failed: email and password are required")
		return errors.New("email and password are required")
	}

	if err := a.client.Authenticate(email, password); err != nil {
		if err.Error() == "invalid credentials" {
			a.logger.Error("Login failed: invalid credentials for email: %s", email)
			return ErrInvalidCredentials
		}
		a.logger.Error("Authentication failed: %v", err)
		return fmt.Errorf("authentication failed: %w", err)
	}

	token := a.client.GetToken()
	if token == "" {
		a.logger.Error("No token received after authentication")
		return fmt.Errorf("no token received after authentication")
	}

	a.mu.Lock()
	a.token = token
	a.expiry = time.Now().Add(24 * time.Hour)
	a.mu.Unlock()

	tokenData := storage.TokenData{
		Token: token,
		Expiry: a.expiry,
		CreatedAt: time.Now(),
	}

	if err := a.store.Save(ctx, tokenData); err != nil {
		a.logger.Error("Failed to save token: %v", err)
		return fmt.Errorf("%w: %v", ErrStorageFailure, err)
	}

	a.logger.Info("Login successful for email: %s", email)
	return nil
}

func (a *AuthManager) GetToken(ctx context.Context) (string, error) {
	a.mu.RLock()
	defer a.mu.RUnlock()

	a.logger.Debug("Retrieving token")

	if time.Now().After(a.expiry) {
		a.token = ""
		a.logger.Warning("Token has expired")
		return "", ErrTokenExpired
	}

	if a.token != "" {
		a.logger.Debug("Using in-memory token")
		return a.token, nil
	}

	tokenData, err := a.store.Load(ctx)
	if err != nil {
		a.logger.Error("Failed to load token from storage: %v", err)
		return "", fmt.Errorf("%w: %v", ErrStorageFailure, err)
	}

	if tokenData == nil {
		a.logger.Warning("No token found in storage")
		return "", ErrNotAuthenticated
	}

	if time.Now().After(tokenData.Expiry) {
		a.logger.Warning("Stored token has expired")
		_ = a.store.Clear(ctx)
		return "", ErrTokenExpired
	}

	a.token = tokenData.Token
	a.expiry = tokenData.Expiry
	a.logger.Debug("Successfully retrieved token from storage")

	return a.token, nil
}

func (a *AuthManager) IsAuthenticated() bool {
	a.mu.RLock()
	defer a.mu.RUnlock()

	a.logger.Debug("Checking authentication status")

	if time.Now().After(a.expiry) {
		a.logger.Debug("Token has expired, not authenticated")
		return false
	}

	if a.token != "" {
		a.logger.Debug("Valid token in memory, authenticated")
		return true
	}

	tokenData, err := a.store.Load(context.Background())
	if err != nil || tokenData == nil {
		a.logger.Debug("No valid token in storage, not authenticated")
		return false
	}

	if time.Now().After(tokenData.Expiry) {
		a.logger.Debug("Stored token has expired, not authenticated")
		return false
	}

	a.logger.Debug("Valid token found in storage, authenticated")
	return true
}

func (a *AuthManager) Logout() error {
	a.logger.Debug("Processing logout request")

	a.mu.Lock()
	defer a.mu.Unlock()

	a.token = ""
	a.expiry = time.Time{}

	if err := a.store.Clear(context.Background()); err != nil {
		a.logger.Error("Failed to clear token storage: %v", err)
		return fmt.Errorf("%w: %v", ErrStorageFailure, err)
	}

	a.logger.Info("Logout successful")
	return nil
}

func (a *AuthManager) tryAutoLogin(ctx context.Context) error {
	a.logger.Debug("Attempting auto-login")

	tokenData, err := a.store.Load(ctx)
	if err != nil {
		a.logger.Error("Failed to load token for auto-login: %v", err)
		return fmt.Errorf("%w: %v", ErrStorageFailure, err)
	}

	if tokenData == nil || time.Now().After(tokenData.Expiry) {
		a.logger.Warning("No valid token found for auto-login")
		return ErrTokenExpired
	}

	a.mu.Lock()
	defer a.mu.Unlock()

	a.token = tokenData.Token
	a.expiry = tokenData.Expiry

	a.logger.Info("Auto-login successful")
	return nil
}

func (a *AuthManager) loadTokenFromStore(ctx context.Context) (*storage.TokenData, error) {
	a.logger.Debug("Loading token from storage")

	tokenData, err := a.store.Load(ctx)
	if err != nil {
		a.logger.Error("Failed to load token from storage: %v", err)
		return nil, fmt.Errorf("%w: %v", ErrStorageFailure, err)
	}

	if tokenData != nil {
		a.logger.Debug("Successfully loaded token from storage")
	} else {
		a.logger.Debug("No token found in storage")
	}

	return tokenData, nil
}

func (a *AuthManager) saveTokenToStore(ctx context.Context, token string, expiry time.Time) error {
	a.logger.Debug("Saving token to storage")

	tokenData := storage.TokenData{
		Token: token,
		Expiry: expiry,
		CreatedAt: time.Now(),
	}
	
	if err := a.store.Save(ctx, tokenData); err != nil {
		a.logger.Error("Failed to save token to storage: %v", err)
		return fmt.Errorf("%w: %v", ErrStorageFailure, err)
	}

	a.logger.Debug("Successfully saved token to storage")
	return nil
}

func (a *AuthManager) updateInMemoryToken(token string, expiry time.Time) {
	a.logger.Debug("Updating in-memory token")
	
	a.mu.Lock()
	defer a.mu.Unlock()
	a.token = token
	a.expiry = expiry

	a.logger.Debug("In-memory token updated")
}

