			password: validPassword,
			setup: func(t *testing.T) *aiyou.Client {
				return &aiyou.Client{}
			},
			wantErr: false,
		},
		{
			name:     "empty email",
			email:    "",
			password: validPassword,
			setup: func(t *testing.T) *aiyou.Client {
				return &aiyou.Client{}
			},
			wantErr: true,
		},
		{
			name:     "empty password",
			email:    validEmail,
			password: "",
			setup: func(t *testing.T) *aiyou.Client {
				return &aiyou.Client{}
			},
			wantErr: true,
