// TestNewMemoryCache vérifie la création correcte d'une instance de cache.
func TestNewMemoryCache(t *testing.T) {
	t.Run("création avec configuration valide", func(t *testing.T) {
		config := cache.DefaultConfig()
		c, err := NewMemoryCache(config)
		require.NoError(t, err)
		require.NotNil(t, c)
		defer c.Close()

		stats := c.GetStats(context.Background())
		assert.Equal(t, 0, stats.ItemCount)
		assert.Equal(t, int64(0), stats.Size)
	})

	t.Run("vérification des valeurs par défaut", func(t *testing.T) {
		config := cache.DefaultConfig()
		c, err := NewMemoryCache(config)
		require.NoError(t, err)
		defer c.Close()

		mc := c.(*memoryCache)
		assert.Equal(t, config.MaxSize, mc.config.MaxSize)
		assert.Equal(t, config.CleanupInterval, mc.config.CleanupInterval)
	})
}

// TestMemoryCache_Set teste les opérations de stockage dans le cache.
func TestMemoryCache_Set(t *testing.T) {
	ctx := context.Background()
	config := cache.DefaultConfig()
	c, err := NewMemoryCache(config)
	require.NoError(t, err)
	defer c.Close()

	tests := []struct {
		name      string
		key       string
		value     interface{}
		cacheType cache.CacheType
		wantErr   bool
	}{
		{
			name:      "stockage valeur simple",
			key:       "test1",
			value:     "value1",
			cacheType: cache.QueryCache,
			wantErr:   false,
		},
		{
			name:      "clé vide",
			key:       "",
			value:     "value2",
			cacheType: cache.QueryCache,
			wantErr:   true,
		},
		{
			name:      "valeur nil",
			key:       "test3",
			value:     nil,
			cacheType: cache.QueryCache,
			wantErr:   true,
		},
		{
			name:      "grande valeur",
			key:       "test4",
			value:     make([]byte, config.MaxSize+1),
			cacheType: cache.QueryCache,
			wantErr:   true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := c.Set(ctx, tt.key, tt.value, tt.cacheType)
			if tt.wantErr {
				assert.Error(t, err)
			} else {
				assert.NoError(t, err)
				entry, exists := c.Get(ctx, tt.key)
				assert.True(t, exists)
				assert.Equal(t, tt.value, entry.Value)
			}
		})
	}
}

// TestMemoryCache_Get teste les opérations de récupération du cache.
func TestMemoryCache_Get(t *testing.T) {
	ctx := context.Background()
	c, err := NewMemoryCache(cache.DefaultConfig())
	require.NoError(t, err)
	defer c.Close()

	t.Run("vérification statistiques", func(t *testing.T) {
		// Réinitialisation des stats
		err := c.Clear(ctx)
		require.NoError(t, err)

		err = c.Set(ctx, "stats", "value", cache.QueryCache)
		require.NoError(t, err)

		// Premier accès (hit)
		_, exists := c.Get(ctx, "stats")
		require.True(t, exists)

		// Accès manqué (miss)
		_, exists = c.Get(ctx, "missing")
		require.False(t, exists)

		stats := c.GetStats(ctx)
		assert.Equal(t, int64(1), stats.HitCount, "Hit count devrait être 1")
		assert.Equal(t, int64(1), stats.MissCount, "Miss count devrait être 1")
	})
}

// TestMemoryCache_Delete teste les opérations de suppression du cache.
func TestMemoryCache_Delete(t *testing.T) {
	ctx := context.Background()
	c, err := NewMemoryCache(cache.DefaultConfig())
	require.NoError(t, err)
	defer c.Close()

	t.Run("suppression valeur existante", func(t *testing.T) {
		err := c.Set(ctx, "key", "value", cache.QueryCache)
		require.NoError(t, err)

		err = c.Delete(ctx, "key")
		assert.NoError(t, err)

		_, exists := c.Get(ctx, "key")
		assert.False(t, exists)
	})

	t.Run("suppression valeur inexistante", func(t *testing.T) {
		err = c.Delete(ctx, "nonexistent")
		assert.NoError(t, err)
	})

	t.Run("vérification taille après suppression", func(t *testing.T) {
		err := c.Set(ctx, "size_test", "value", cache.QueryCache)
		require.NoError(t, err)

		statsBefore := c.GetStats(ctx)
		err = c.Delete(ctx, "size_test")
		require.NoError(t, err)
		statsAfter := c.GetStats(ctx)

		assert.Greater(t, statsBefore.Size, statsAfter.Size)
	})
}

// TestMemoryCache_Clear teste le nettoyage complet du cache.
func TestMemoryCache_Clear(t *testing.T) {
	ctx := context.Background()
	c, err := NewMemoryCache(cache.DefaultConfig())
	require.NoError(t, err)
	defer c.Close()

	// Ajout de plusieurs entrées
	for i := 0; i < 5; i++ {
		err := c.Set(ctx, fmt.Sprintf("key%d", i), i, cache.QueryCache)
		require.NoError(t, err)
	}

	// Vérification avant Clear
	statsBefore := c.GetStats(ctx)
	assert.Greater(t, statsBefore.ItemCount, 0)

	// Clear
	err = c.Clear(ctx)
	require.NoError(t, err)

	// Vérification après Clear
	statsAfter := c.GetStats(ctx)
	assert.Equal(t, 0, statsAfter.ItemCount)
	assert.Equal(t, int64(0), statsAfter.Size)
}

// TestMemoryCache_Concurrent teste les accès concurrents au cache.
func TestMemoryCache_Concurrent(t *testing.T) {
	ctx := context.Background()
	c, err := NewMemoryCache(cache.DefaultConfig())
	require.NoError(t, err)
	defer c.Close()

	const goroutines = 10
	const operationsPerGoroutine = 100

	var wg sync.WaitGroup
	wg.Add(goroutines)

	for i := 0; i < goroutines; i++ {
		go func(id int) {
			defer wg.Done()
			for j := 0; j < operationsPerGoroutine; j++ {
				key := fmt.Sprintf("key%d-%d", id, j)

				// Set
				err := c.Set(ctx, key, j, cache.QueryCache)
				assert.NoError(t, err)

				// Get
				_, _ = c.Get(ctx, key)

				// Delete
				err = c.Delete(ctx, key)
				assert.NoError(t, err)
			}
		}(i)
	}

	wg.Wait()
}

// TestMemoryCache_Cleanup teste le nettoyage automatique des entrées expirées.
func TestMemoryCache_Cleanup(t *testing.T) {
	ctx := context.Background()
	config := cache.DefaultConfig()
	config.CleanupInterval = 50 * time.Millisecond
	config.QueryTTL = 100 * time.Millisecond

	c, err := NewMemoryCache(config)
	require.NoError(t, err)
	defer c.Close()

	// Ajout d'entrées
	err = c.Set(ctx, "test", "value", cache.QueryCache)
	require.NoError(t, err)

	// Vérification initiale
	statsBefore := c.GetStats(ctx)
	assert.Equal(t, 1, statsBefore.ItemCount)

	// Attente de l'expiration et du nettoyage
	time.Sleep(200 * time.Millisecond)

	// Vérification après nettoyage
	statsAfter := c.GetStats(ctx)
	assert.Equal(t, 0, statsAfter.ItemCount)
}

// TestMemoryCache_Context teste la gestion du contexte.
func TestMemoryCache_Context(t *testing.T) {
	c, err := NewMemoryCache(cache.DefaultConfig())
	require.NoError(t, err)
	defer c.Close()

	ctx, cancel := context.WithCancel(context.Background())
	cancel() // Annulation immédiate du contexte

	t.Run("Set avec contexte annulé", func(t *testing.T) {
		err := c.Set(ctx, "key", "value", cache.QueryCache)
		assert.Error(t, err)
	})

	t.Run("Get avec contexte annulé", func(t *testing.T) {
		_, exists := c.Get(ctx, "key")
		assert.False(t, exists)
	})

	t.Run("Delete avec contexte annulé", func(t *testing.T) {
		err := c.Delete(ctx, "key")
		assert.Error(t, err)
	})

	t.Run("Clear avec contexte annulé", func(t *testing.T) {
		err := c.Clear(ctx)
		assert.Error(t, err)
	})
}

// BenchmarkMemoryCache_Set effectue des tests de performance pour l'opération Set.
func BenchmarkMemoryCache_Set(b *testing.B) {
	ctx := context.Background()
	c, _ := NewMemoryCache(cache.DefaultConfig())
	defer c.Close()

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		key := fmt.Sprintf("key%d", i)
		_ = c.Set(ctx, key, "value", cache.QueryCache)
	}
}

// BenchmarkMemoryCache_Get effectue des tests de performance pour l'opération Get.
func BenchmarkMemoryCache_Get(b *testing.B) {
	ctx := context.Background()
	c, _ := NewMemoryCache(cache.DefaultConfig())
	defer c.Close()

	// Préparation des données
	_ = c.Set(ctx, "bench_key", "value", cache.QueryCache)

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		_, _ = c.Get(ctx, "bench_key")
	}
}

// Package cache fournit une interface et une implémentation pour la gestion du cache
// dans l'application AI.YOU CLI. Il permet de stocker temporairement différents types
// de données avec des durées de vie configurables et une gestion automatique de l'expiration.
package cache

import (
	"context"
	"errors"
	"time"
)

// Définition des erreurs standard du système de cache.
// Ces erreurs sont utilisées pour identifier clairement les problèmes courants.
var (
	// ErrCacheKeyNotFound est retourné lorsqu'une clé n'existe pas dans le cache
	ErrCacheKeyNotFound = errors.New("cache key not found")

	// ErrCacheKeyInvalid est retourné lorsqu'une clé de cache est invalide (vide par exemple)
	ErrCacheKeyInvalid = errors.New("invalid cache key")

	// ErrCacheValueInvalid est retourné lorsqu'une valeur ne peut pas être mise en cache
	ErrCacheValueInvalid = errors.New("invalid cache value")

	// ErrCacheFull est retourné lorsque le cache a atteint sa taille maximale
	ErrCacheFull = errors.New("cache is full")
)

// CacheType représente les différents types de données pouvant être mis en cache.
// Chaque type peut avoir des paramètres de durée de vie différents.
type CacheType string

// Définition des différents types de cache supportés par le système.
const (
	// AssistantCache stocke les informations relatives aux assistants AI
	AssistantCache CacheType = "assistant"

	// QueryCache stocke les résultats des requêtes fréquentes
	QueryCache CacheType = "query"

	// ModelCache stocke les métadonnées des modèles AI
	ModelCache CacheType = "model"

	// UserCache stocke les informations temporaires sur l'utilisateur
	UserCache CacheType = "user"

	// ConfigCache stocke les configurations qui changent peu fréquemment
	ConfigCache CacheType = "config"
)

// CacheEntry représente une entrée individuelle dans le cache.
// Elle contient la valeur stockée ainsi que des métadonnées associées.
type CacheEntry struct {
	// Value contient la donnée mise en cache
	Value interface{}

	// Expiration définit le moment où l'entrée devient invalide
	Expiration time.Time

	// Type identifie le type de donnée stockée
	Type CacheType

	// Size représente la taille approximative en bytes de l'entrée
	Size int64

	// CreatedAt est l'horodatage de création de l'entrée
	CreatedAt time.Time

	// LastAccess est l'horodatage du dernier accès à l'entrée
	LastAccess time.Time
}

// CacheStats maintient des statistiques sur l'utilisation du cache.
// Ces informations sont utiles pour le monitoring et l'optimisation.
type CacheStats struct {
	// ItemCount représente le nombre total d'éléments dans le cache
	ItemCount int

	// Size représente la taille totale occupée par le cache en bytes
	Size int64

	// HitCount compte le nombre d'accès réussis au cache
	HitCount int64

	// MissCount compte le nombre d'accès manqués au cache
	MissCount int64
}

// CacheConfig définit les paramètres de configuration du cache.
// Elle permet de personnaliser le comportement du cache selon les besoins.
type CacheConfig struct {
	// Durées de vie pour chaque type de cache
	AssistantTTL time.Duration
	QueryTTL     time.Duration
	ModelTTL     time.Duration
	UserTTL      time.Duration
	ConfigTTL    time.Duration
	DefaultTTL   time.Duration

	// MaxSize définit la taille maximale du cache en bytes
	MaxSize int64

	// CleanupInterval définit la fréquence de nettoyage des entrées expirées
	CleanupInterval time.Duration
}

// DefaultConfig retourne une configuration par défaut pour le cache.
// Ces valeurs peuvent être ajustées selon les besoins spécifiques.
func DefaultConfig() CacheConfig {
	return CacheConfig{
		AssistantTTL:    time.Hour,        // 1 heure pour les assistants
		QueryTTL:        15 * time.Minute, // 15 minutes pour les requêtes
		ModelTTL:        24 * time.Hour,   // 24 heures pour les modèles
		UserTTL:         time.Hour,        // 1 heure pour les données utilisateur
		ConfigTTL:       12 * time.Hour,   // 12 heures pour les configurations
		DefaultTTL:      time.Hour,        // 1 heure par défaut
		MaxSize:         10 * 1024 * 1024, // 10MB maximum
		CleanupInterval: 10 * time.Minute, // Nettoyage toutes les 10 minutes
	}
}

// Cache définit l'interface pour toutes les opérations de cache supportées.
// Cette interface peut être implémentée par différents backends de stockage.
type Cache interface {
	// Set ajoute ou met à jour une entrée dans le cache.
	// Retourne une erreur si l'opération échoue.
	Set(ctx context.Context, key string, value interface{}, cacheType CacheType) error

	// Get récupère une entrée du cache.
	// Retourne l'entrée et un booléen indiquant si elle a été trouvée.
	Get(ctx context.Context, key string) (CacheEntry, bool)

	// Delete supprime une entrée du cache.
	// Retourne une erreur si l'opération échoue.
	Delete(ctx context.Context, key string) error

	// Clear vide entièrement le cache.
	// Retourne une erreur si l'opération échoue.
	Clear(ctx context.Context) error

	// GetStats retourne les statistiques actuelles du cache.
	GetStats(ctx context.Context) CacheStats

	// Close ferme proprement le cache et libère les ressources.
	// Doit être appelé lors de l'arrêt de l'application.
	Close() error
}

// Package cli provides the command-line interface implementation.
package cli

import (
	"context"
	"fmt"
	"io"
	"os"
	"sync"

	"github.com/chrlesur/aiyou.cli/internal/api"
	"github.com/chrlesur/aiyou.cli/internal/cache"
	"github.com/chrlesur/aiyou.cli/internal/cache/memory"
	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.cli/internal/interfaces"
	"github.com/chrlesur/aiyou.cli/pkg/logger"
	"github.com/chrlesur/aiyou.golib/pkg/aiyou"
	"github.com/spf13/cobra"
)

// AppConfig holds the configuration for creating a new App instance
type AppConfig struct {
	Version string
	Config  *config.Config
}

// ClientAdapter adapts the aiyou.Client to implement the AIClient interface
type ClientAdapter struct {
	*aiyou.Client
	isAuthenticated bool
	token           string
	mu              sync.RWMutex
	logger          *logger.Logger
}

// NewClientAdapter creates a new adapter for the client with proper logging
func NewClientAdapter(client *aiyou.Client) *ClientAdapter {
	log := logger.GetLogger()
	log.Debug("Creating new client adapter")

	return &ClientAdapter{
		Client:          client,
		logger:          log,
		isAuthenticated: false,
	}
}

// GetToken implements the interface method with logging
func (ca *ClientAdapter) GetToken() string {
	ca.mu.RLock()
	defer ca.mu.RUnlock()

	ca.logger.Debug("Getting token from adapter")
	return ca.token
}

// SetToken implements the interface method with logging
func (ca *ClientAdapter) SetToken(token string) {
	ca.mu.Lock()
	defer ca.mu.Unlock()

	ca.logger.Debug("Setting new token")
	ca.token = token
	ca.isAuthenticated = token != ""
	ca.logger.Debug("Authentication status updated: %v", ca.isAuthenticated)
}

// IsAuthenticated returns the authentication status with logging
func (ca *ClientAdapter) IsAuthenticated() bool {
	ca.mu.RLock()
	defer ca.mu.RUnlock()

	ca.logger.Debug("Checking authentication status: %v", ca.isAuthenticated)
	return ca.isAuthenticated
}

// Authenticate implements the interface method with logging
func (ca *ClientAdapter) Authenticate(email, password string) error {
	ca.logger.Debug("Attempting authentication for email: %s", email)

	if email == "" || password == "" {
		ca.logger.Error("Authentication failed: empty credentials")
		return fmt.Errorf("email and password are required")
	}

	ca.mu.Lock()
	ca.isAuthenticated = true
	ca.mu.Unlock()

	ca.logger.Info("Authentication successful for email: %s", email)
	return nil
}

// RefreshToken implements the interface method with logging
func (ca *ClientAdapter) RefreshToken() error {
	ca.logger.Debug("Token refresh requested")
	return nil
}

// App represents the CLI application structure
type App struct {
	rootCmd       *cobra.Command
	cfg           *config.Config
	logger        *logger.Logger
	version       string
	client        interfaces.AIClient
	cache         cache.Cache
	isLoggedIn    bool
	closeOnce     sync.Once
	isClosed      bool
	authManager   *api.AuthManager
	chatManager   *api.ChatManager
	threadManager *api.ThreadManager
	stdin         io.Reader
}

// NewApp creates and initializes a new CLI application
func NewApp(cfg *AppConfig) (*App, error) {
	log := logger.GetLogger()
	log.Debug("Initializing new CLI application")

	if cfg == nil {
		log.Error("Failed to create app: config is required")
		return nil, fmt.Errorf("app config is required")
	}

	// Initialize cache
	log.Debug("Initializing cache")
	cacheConfig := cache.DefaultConfig()
	cacheInstance, err := memory.NewMemoryCache(cacheConfig)
	if err != nil {
		log.Error("Failed to initialize cache: %v", err)
		return nil, fmt.Errorf("failed to initialize cache: %w", err)
	}

	// Initialize aiyou.golib client
	log.Debug("Initializing API client")
	baseClient, err := aiyou.NewClient("", "")
	if err != nil {
		cacheInstance.Close()
		log.Error("Failed to initialize API client: %v", err)
		return nil, fmt.Errorf("failed to initialize API client: %w", err)
	}

	// Create adapter
	clientAdapter := NewClientAdapter(baseClient)

	// Initialize auth manager
	log.Debug("Initializing auth manager")
	authManager, err := api.NewAuthManager(baseClient, cfg.Config)
	if err != nil {
		cacheInstance.Close()
		log.Error("Failed to initialize auth manager: %v", err)
		return nil, fmt.Errorf("failed to initialize auth manager: %w", err)
	}

	// Initialize chat manager
	log.Debug("Initializing chat manager")
	chatManager, err := api.NewChatManager(api.ChatManagerConfig{
		Client: clientAdapter,
		Cache:  cacheInstance,
		Config: cfg.Config,
	})
	if err != nil {
		cacheInstance.Close()
		log.Error("Failed to initialize chat manager: %v", err)
		return nil, fmt.Errorf("failed to initialize chat manager: %w", err)
	}

	// Initialize thread manager
	log.Debug("Initializing thread manager")
	threadManager, err := api.NewThreadManager(api.ThreadManagerConfig{
		Client: clientAdapter,
		Cache:  cacheInstance,
		Config: cfg.Config,
	})
	if err != nil {
		cacheInstance.Close()
		log.Error("Failed to initialize thread manager: %v", err)
		return nil, fmt.Errorf("failed to initialize thread manager: %w", err)
	}

	app := &App{
		cfg:           cfg.Config,
		logger:        log,
		version:       cfg.Version,
		client:        clientAdapter,
		cache:         cacheInstance,
		authManager:   authManager,
		chatManager:   chatManager,
		threadManager: threadManager,
		stdin:         os.Stdin,
	}

	log.Debug("Initializing root command")
	app.initializeRootCommand()
	app.registerCommands()

	log.Info("CLI application initialized successfully")
	return app, nil
}

// Run executes the CLI application
func (a *App) Run(ctx context.Context) error {
	a.logger.Debug("Starting CLI application")

	if a.isClosed {
		a.logger.Error("Cannot run: app is already closed")
		return fmt.Errorf("app is already closed")
	}

	defer func() {
		a.closeOnce.Do(func() {
			if a.cache != nil {
				if err := a.cache.Close(); err != nil {
					a.logger.Error("Error closing cache: %v", err)
				}
			}
			a.isClosed = true
			a.logger.Debug("Application resources cleaned up")
		})
	}()

	a.logger.Debug("Executing root command")
	return a.rootCmd.ExecuteContext(ctx)
}

// Close properly closes the application resources
func (a *App) Close() error {
	a.logger.Debug("Closing application")

	var err error
	a.closeOnce.Do(func() {
		if a.cache != nil {
			if closeErr := a.cache.Close(); closeErr != nil {
				a.logger.Error("Failed to close cache: %v", closeErr)
				err = closeErr
			}
		}
		a.isClosed = true
		a.logger.Info("Application closed successfully")
	})
	return err
}

// initializeRootCommand sets up the root command and global flags
func (a *App) initializeRootCommand() {
	a.logger.Debug("Setting up root command")

	a.rootCmd = &cobra.Command{
		Use:   "aiyou",
		Short: "AI.YOU Command Line Interface",
		Long: `A powerful command line interface for interacting with AI.YOU services.
Complete documentation is available at https://docs.aiyou.cloud`,
		Version: a.version,
		PersistentPreRunE: func(cmd *cobra.Command, args []string) error {
			// Skip auth check for certain commands
			if cmd.Name() == "login" || cmd.Name() == "version" || cmd.Name() == "help" {
				return nil
			}

			// Verify authentication for other commands
			if !a.isLoggedIn {
				a.logger.Warning("Command requires authentication but user is not logged in")
				return fmt.Errorf("authentication required: please login first using 'aiyou login'")
			}

			return nil
		},
		SilenceUsage: true,
	}

	// Global flags
	a.rootCmd.PersistentFlags().Bool("debug", false, "enable debug mode")
	a.rootCmd.PersistentFlags().String("config", "", "config file (default is $HOME/.aiyou/config.yaml)")
	a.rootCmd.PersistentFlags().Bool("verbose", false, "print all non-error output")

	a.logger.Debug("Root command initialized with flags")
}

// registerCommands adds all available commands to the CLI
func (a *App) registerCommands() {
	a.logger.Debug("Registering CLI commands")

	a.rootCmd.AddCommand(
		a.newLoginCmd(),
		a.newLogoutCmd(),
		a.newVersionCmd(),
		a.newCompletionCmd(),
		a.newConfigCmd(),
		a.newChatCmd(),
		a.newThreadCmd(),
	)

	a.logger.Debug("Commands registered successfully")
}

// GetClient returns the API client
func (a *App) GetClient() interfaces.AIClient {
	return a.client
}

// SetLoggedIn sets the login status
func (a *App) SetLoggedIn(status bool) {
	a.logger.Debug("Setting login status to: %v", status)
	a.isLoggedIn = status
}

// IsLoggedIn returns the current login status
func (a *App) IsLoggedIn() bool {
	return a.isLoggedIn
}

// startProgress displays a progress indicator with a message
func (a *App) startProgress(message string) {
	if !a.cfg.ShowProgress {
		return
	}
	a.logger.Debug("Starting progress: %s", message)
	fmt.Printf("%s... ", message)
}

// stopProgress stops the progress indicator
func (a *App) stopProgress() {
	if !a.cfg.ShowProgress {
		return
	}
	a.logger.Debug("Stopping progress indicator")
	fmt.Println("done")
}

// newVersionCmd creates the version command
func (a *App) newVersionCmd() *cobra.Command {
	a.logger.Debug("Creating version command")

	cmd := &cobra.Command{
		Use:   "version",
		Short: "Print the version information",
		Run: func(cmd *cobra.Command, args []string) {
			a.logger.Debug("Executing version command")
			fmt.Printf("aiyou CLI version %s\n", a.version)
		},
	}

	return cmd
}

// newCompletionCmd creates the shell completion command
func (a *App) newCompletionCmd() *cobra.Command {
	a.logger.Debug("Creating completion command")

	cmd := &cobra.Command{
		Use:       "completion [bash|zsh|fish|powershell]",
		Short:     "Generate completion script",
		Long:      "Generate shell completion script for aiyou CLI",
		ValidArgs: []string{"bash", "zsh", "fish", "powershell"},
		Args:      cobra.ExactValidArgs(1),
		Run: func(cmd *cobra.Command, args []string) {
			a.logger.Debug("Generating completion script for shell: %s", args[0])

			var err error
			switch args[0] {
			case "bash":
				err = a.rootCmd.GenBashCompletion(os.Stdout)
			case "zsh":
				err = a.rootCmd.GenZshCompletion(os.Stdout)
			case "fish":
				err = a.rootCmd.GenFishCompletion(os.Stdout, true)
			case "powershell":
				err = a.rootCmd.GenPowerShellCompletion(os.Stdout)
			}

			if err != nil {
				a.logger.Error("Failed to generate completion script: %v", err)
			} else {
				a.logger.Info("Successfully generated completion script for %s", args[0])
			}
		},
	}

	return cmd
}

// newConfigCmd creates the config command
func (a *App) newConfigCmd() *cobra.Command {
	a.logger.Debug("Creating config command")

	cmd := &cobra.Command{
		Use:   "config",
		Short: "Manage configuration",
		Long:  `View and modify configuration settings for aiyou CLI.`,
		Run: func(cmd *cobra.Command, args []string) {
			a.logger.Debug("Displaying current configuration")

			fmt.Printf("Configuration:\n")
			fmt.Printf(" API Endpoint: %s\n", a.cfg.APIEndpoint)
			fmt.Printf(" Log Level: %s\n", a.cfg.LogLevel)
			fmt.Printf(" Max Threads: %d\n", a.cfg.MaxThreads)
			fmt.Printf(" Debug Mode: %v\n", a.cfg.Debug)

			a.logger.Debug("Configuration displayed successfully")
		},
	}

	return cmd
}

package cli

import (
	"context"
	"testing"

	"github.com/chrlesur/aiyou.cli/internal/config"
